function renderStats(){const e=document.getElementById("stats-grid");e&&"undefined"!=typeof SIKH_EMPIRE_INFO&&(e.innerHTML=SIKH_EMPIRE_INFO.quickStats.map(e=>`\n        <div class="stat-card">\n            <span class="stat-icon">${e.icon}</span>\n            <div class="stat-val">${e.value}</div>\n            <div class="stat-lbl">${e.label}</div>\n        </div>\n    `).join(""))}function renderTimeline(){const e=document.getElementById("timeline-container");e&&"undefined"!=typeof TIMELINE_DATA&&(e.innerHTML=TIMELINE_DATA.map(e=>`\n        <div class="timeline-card">\n            <div class="timeline-year">${e.year}</div>\n            <div class="timeline-content">\n                <h3>${e.title}</h3>\n                <p>${e.description}</p>\n            </div>\n        </div>\n    `).join(""))}function renderRulers(){const e=document.getElementById("rulers-grid");e&&"undefined"!=typeof RULERS_DATA&&(e.innerHTML=RULERS_DATA.map(e=>`\n        <div class="ruler-card">\n            <h3>👑 ${e.name}</h3>\n            <span class="ruler-role">${e.role}</span>\n            <p>${e.achievements}</p>\n        </div>\n    `).join(""))}function renderContributions(){if("undefined"==typeof CONTRIBUTIONS_DATA)return;const e=document.getElementById("contrib-overview"),n=document.getElementById("contrib-army"),t=document.getElementById("contrib-temple"),r=document.getElementById("contrib-secular"),i=document.getElementById("contrib-border");e&&(e.innerHTML=`<strong>Overview:</strong> ${CONTRIBUTIONS_DATA.overview}`),n&&(n.innerHTML=`<strong>Fauj-i-Khas Military Modernization:</strong> ${CONTRIBUTIONS_DATA.faujIKhas}`),t&&(t.innerHTML=`<strong>Golden Temple Architecture:</strong> ${CONTRIBUTIONS_DATA.harmandirSahib}`),r&&(r.innerHTML=`<strong>Secular Governance & Equality:</strong> ${CONTRIBUTIONS_DATA.secularGovernance}`),i&&(i.innerHTML=`<strong>Northwest Border Security:</strong> ${CONTRIBUTIONS_DATA.borderSecurity}`)}function renderGallery(){const e=document.getElementById("gallery-grid");e&&"undefined"!=typeof GALLERY_IMAGES&&(e.innerHTML=GALLERY_IMAGES.map(e=>`\n        <div class="gallery-card">\n            <img src="${e.url}" alt="${e.caption}" loading="lazy" />\n            <p>${e.caption}</p>\n        </div>\n    `).join(""))}function renderReferences(){const e=document.getElementById("references-list");e&&"undefined"!=typeof REFERENCES&&(e.innerHTML=REFERENCES.map(e=>`\n        <li>\n            <a href="${e.link}" target="_blank" rel="noopener noreferrer">📚 ${e.text}</a>\n        </li>\n    `).join(""))}function initThemeToggle(){const e=document.getElementById("theme-toggle");e&&e.addEventListener("click",()=>{const n=document.body.classList.toggle("light-theme");localStorage.setItem("theme",n?"light":"dark"),e.textContent=n?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderTimeline(),renderRulers(),renderContributions(),renderGallery(),renderReferences(),initThemeToggle()});